(()=>{const page=document.getElementById('emilie-page');function update(){const active=location.hash==='#project/emilie-chamie';document.body.classList.toggle('emilie-active',active);page.hidden=!active;if(!active)page.querySelector('video').pause();}window.addEventListener('portfolio:route',e=>{const active=e.detail==='project/emilie-chamie';document.body.classList.toggle('emilie-active',active);page.hidden=!active;if(!active)page.querySelector('video').pause();});update();if('IntersectionObserver' in window&&!matchMedia('(prefers-reduced-motion:reduce)').matches){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('ec-visible');observer.unobserve(e.target);}})},{threshold:0,rootMargin:'0px 0px -35px 0px'});page.querySelectorAll('.ec-reveal').forEach(el=>{el.classList.add('ec-pending');observer.observe(el);});}})();